    public async Task<DoctorDto> RegisterDoctorAsync(RegisterDoctorRequest request, CancellationToken cancellationToken)
    {
        if (currentUser.UserType != UserType.Doctor)
        {
            throw new ForbiddenException();
        }

        if (await dbContext.Doctors.AnyAsync(x => x.UserId == currentUser.UserId, cancellationToken))
        {
            throw new ConflictException("Doctor profile already exists.");
        }

        var normalized = NormalizeRegistration(request.RegistrationNumber);
        var configuredHashKey = configuration["Registration:HashKey"] ?? configuration["Jwt:Key"]
            ?? throw new InvalidOperationException("Registration:HashKey or Jwt:Key is required.");
        var purposeKey = SHA256.HashData(Encoding.UTF8.GetBytes($"FamilyVeda.DoctorRegistration.v1:{configuredHashKey}"));
        var hash = Convert.ToHexString(HMACSHA256.HashData(purposeKey, Encoding.UTF8.GetBytes(normalized)));
        if (await dbContext.Doctors.AnyAsync(x => x.RegistrationNumberHash == hash, cancellationToken))
        {
            throw new ConflictException("Registration number is already registered.");
        }

        var doctor = new Doctor
        {
            UserId = currentUser.UserId,
            RegistrationNumberHash = hash,
            RegistrationNumberLastFour = normalized[^Math.Min(4, normalized.Length)..],
            Specialty = request.Specialty?.Trim(),
            HospitalClinic = request.HospitalClinic?.Trim(),
            PhoneNumber = request.PhoneNumber?.Trim()
        };
        dbContext.Doctors.Add(doctor);
        var metadata = System.Text.Json.JsonSerializer.Serialize(new
        {
            RegistrationNumber = request.RegistrationNumber?.Trim(),
            Specialization = request.Specialty?.Trim(),
            HospitalClinic = request.HospitalClinic?.Trim(),
            PhoneNumber = request.PhoneNumber?.Trim(),
            RegistrationNumberLastFour = doctor.RegistrationNumberLastFour
        });
        await WriteAuditAsync("DOCTOR_REGISTERED", "Doctor", doctor.Id, "PENDING", cancellationToken, metadataJson: metadata);
        await dbContext.SaveChangesAsync(cancellationToken);
        return MapDoctor(doctor, request.RegistrationNumber?.Trim());
    }

    public async Task<DoctorDto> GetMyDoctorAsync(CancellationToken cancellationToken)
    {
        var doctor = await dbContext.Doctors.AsNoTracking().Include(x => x.User).SingleOrDefaultAsync(x => x.UserId == currentUser.UserId, cancellationToken) ?? throw new NotFoundException();
        return MapDoctor(doctor);
    }

    public async Task<PagedResult<DoctorDto>> GetPendingDoctorsAsync(int page, int pageSize, CancellationToken cancellationToken)
    {
        RequireAdmin();
        (page, pageSize) = NormalizePage(page, pageSize);
        var doctors = await dbContext.Doctors.AsNoTracking()
            .Include(x => x.User)
            .OrderByDescending(x => x.VerificationStatus == VerificationStatus.Pending)
            .ThenByDescending(x => x.CreatedAt)
            .ToListAsync(cancellationToken);

        var doctorIds = doctors.Select(d => d.Id).ToList();
        var userIds = doctors.Select(d => d.UserId).ToList();

        var auditLogs = await dbContext.AuditLogs.AsNoTracking()
            .Where(a => a.ResourceType == "Doctor" && a.ResourceId.HasValue && (doctorIds.Contains(a.ResourceId.Value) || userIds.Contains(a.ResourceId.Value)))
            .OrderByDescending(a => a.CreatedAt)
            .ToListAsync(cancellationToken);

        var auditsByDoctor = auditLogs
            .GroupBy(a => a.ResourceId!.Value)
            .ToDictionary(g => g.Key, g => g.ToList());

        var items = doctors.Select(x =>
        {
            var hospital = x.HospitalClinic;
            var phone = x.PhoneNumber;
            var specialty = x.Specialty;
            string? regNumber = null;

            List<AuditLog>? userAudits = null;
            if (auditsByDoctor.TryGetValue(x.Id, out var da)) userAudits = da;
            else if (auditsByDoctor.TryGetValue(x.UserId, out var ua)) userAudits = ua;

            if (userAudits != null)
            {
                var regAudit = userAudits.FirstOrDefault(a => a.EventType == "DOCTOR_REGISTERED");
                if (regAudit?.MetadataJson != null)
                {
                    try
                    {
                        using var doc = System.Text.Json.JsonDocument.Parse(regAudit.MetadataJson);
                        if (string.IsNullOrEmpty(hospital) && doc.RootElement.TryGetProperty("HospitalClinic", out var hElem)) hospital = hElem.GetString();
                        if (string.IsNullOrEmpty(phone) && doc.RootElement.TryGetProperty("PhoneNumber", out var pElem)) phone = pElem.GetString();
                        if (string.IsNullOrEmpty(specialty) && doc.RootElement.TryGetProperty("Specialization", out var sElem)) specialty = sElem.GetString();
                        if (doc.RootElement.TryGetProperty("RegistrationNumber", out var rElem)) regNumber = rElem.GetString();
                    }
                    catch { }
                }
            }

            return new DoctorDto(
                x.Id,
                x.UserId,
                x.RegistrationNumberLastFour,
                x.VerificationStatus,
                specialty ?? "General Practice / Family Medicine",
                hospital,
                phone,
                x.User?.DisplayName ?? "Doctor Account",
                x.User?.Email,
                regNumber
            );
        }).ToList();

        var total = items.Count;
        var pagedItems = items.Skip((page - 1) * pageSize).Take(pageSize).ToList();
        return new PagedResult<DoctorDto>(pagedItems, page, pageSize, total);
    }

    public async Task<DoctorDto> ChangeVerificationAsync(Guid doctorId, VerifyDoctorRequest request, CancellationToken cancellationToken)
    {
        RequireAdmin();
        var doctor = await dbContext.Doctors.Include(x => x.User).SingleOrDefaultAsync(x => x.Id == doctorId, cancellationToken)
            ?? await dbContext.Doctors.Include(x => x.User).SingleOrDefaultAsync(x => x.UserId == doctorId, cancellationToken)
            ?? throw new NotFoundException();
        var previous = doctor.VerificationStatus;
        doctor.VerificationStatus = request.Status;

        if (doctor.User != null)
        {
            if (request.Status == VerificationStatus.Suspended || request.Status == VerificationStatus.Rejected)
            {
                doctor.User.IsActive = false;
            }
            else if (request.Status == VerificationStatus.Verified)
            {
                doctor.User.IsActive = true;
            }
        }

        dbContext.DoctorVerificationLogs.Add(new DoctorVerificationLog
        {
            DoctorId = doctor.Id,
            AdminUserId = currentUser.UserId,
            FromStatus = previous,
            ToStatus = request.Status,
            Reason = request.Reason?.Trim()
        });
        await WriteAuditAsync("DOCTOR_VERIFICATION_CHANGED", "Doctor", doctor.Id, "SUCCESS", cancellationToken);
        await dbContext.SaveChangesAsync(cancellationToken);
        return MapDoctor(doctor);
    }

    public async Task<FamilyHeadDto> GetMyFamilyHeadStatusAsync(CancellationToken cancellationToken)
    {
        if (!currentUser.IsAuthenticated || currentUser.UserType != UserType.FamilyUser)
        {
            throw new ForbiddenException();
        }

        var user = await dbContext.Users.SingleOrDefaultAsync(x => x.Id == currentUser.UserId, cancellationToken)
            ?? throw new NotFoundException();

        var family = await dbContext.Families.Include(f => f.Members)
            .FirstOrDefaultAsync(f => f.CreatedByUserId == user.Id || f.Members.Any(m => m.UserId == user.Id && m.Role == FamilyRole.Head), cancellationToken);
        var member = family?.Members.FirstOrDefault(m => m.UserId == user.Id && m.Role == FamilyRole.Head);

        var auditLogs = await dbContext.AuditLogs.AsNoTracking()
            .Where(a => a.ResourceType == "FamilyHead" && a.ResourceId == user.Id)
            .OrderByDescending(a => a.CreatedAt)
            .ToListAsync(cancellationToken);

        var latestVerificationAudit = auditLogs.FirstOrDefault(a => a.EventType == "FAMILY_HEAD_VERIFICATION_CHANGED");
        var registrationAudit = auditLogs.FirstOrDefault(a => a.EventType == "FAMILY_HEAD_REGISTERED");

        VerificationStatus status = VerificationStatus.Verified; // family heads are auto-approved; admin can still suspend/reject
        if (latestVerificationAudit != null && Enum.TryParse<VerificationStatus>(latestVerificationAudit.Outcome, out var parsedStatus))
        {
            status = parsedStatus;
        }
        else if (!user.IsActive)
        {
            status = VerificationStatus.Suspended;
        }

        string? nic = null;
        string? address = null;
        string? familyCode = null;

        if (user.Email == "demo-head@example.invalid")
        {
            nic = "••••8921";
            address = "24/B Temple Road, Kandy";
            familyCode = "FV-1001";
        }

        if (registrationAudit?.MetadataJson != null)
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(registrationAudit.MetadataJson);
                if (doc.RootElement.TryGetProperty("Nic", out var nicElem)) nic = nicElem.GetString();
                if (doc.RootElement.TryGetProperty("Address", out var addrElem)) address = addrElem.GetString();
            }
            catch { }
        }

        if (latestVerificationAudit?.MetadataJson != null)
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(latestVerificationAudit.MetadataJson);
                if (doc.RootElement.TryGetProperty("FamilyCode", out var codeElem)) familyCode = codeElem.GetString();
                if (nic == null && doc.RootElement.TryGetProperty("Nic", out var nicElem)) nic = nicElem.GetString();
                if (address == null && doc.RootElement.TryGetProperty("Address", out var addrElem)) address = addrElem.GetString();
            }
            catch { }
        }

        // Registration profile is the source of truth; the NIC is only ever shown masked.
        var profile = await dbContext.UserProfiles.AsNoTracking().SingleOrDefaultAsync(p => p.UserId == user.Id, cancellationToken);
        if (profile is not null)
        {
            nic = MaskNationalId(profile.NationalIdLastFour);
            address = FormatAddress(profile);
        }

        if (status == VerificationStatus.Verified && string.IsNullOrEmpty(familyCode))
        {
            familyCode = family?.FamilyCode;
        }

        return new FamilyHeadDto(
            member?.Id ?? user.Id,
            user.Id,
            family?.Id ?? Guid.Empty,
            family?.Name ?? "Pending Setup",
            user.DisplayName,
            user.Email,
            family?.Members.Count ?? 0,
            status,
            user.IsActive,
            user.CreatedAt,
            nic,
            address,
            familyCode);
    }

