    public async Task<FamilyHeadDto> ChangeFamilyHeadVerificationAsync(Guid userId, VerifyDoctorRequest request, CancellationToken cancellationToken)
    {
        RequireAdmin();
        var user = await dbContext.Users.SingleOrDefaultAsync(x => x.Id == userId && x.UserType == UserType.FamilyUser, cancellationToken)
            ?? throw new NotFoundException();

        var family = await dbContext.Families.Include(f => f.Members)
            .FirstOrDefaultAsync(f => f.CreatedByUserId == user.Id || f.Members.Any(m => m.UserId == user.Id && m.Role == FamilyRole.Head), cancellationToken);

        if (request.Status == VerificationStatus.Suspended || request.Status == VerificationStatus.Rejected)
        {
            user.IsActive = false;
        }
        else if (request.Status == VerificationStatus.Verified)
        {
            user.IsActive = true;
        }

        var existingAudits = await dbContext.AuditLogs
            .Where(a => a.ResourceType == "FamilyHead" && a.ResourceId == user.Id)
            .OrderByDescending(a => a.CreatedAt)
            .ToListAsync(cancellationToken);

        string? nic = null;
        string? address = null;
        string? familyCode = null;

        if (user.Email == "demo-head@example.invalid")
        {
            nic = "••••8921";
            address = "24/B Temple Road, Kandy";
            familyCode = "FV-1001";
        }

        foreach (var audit in existingAudits)
        {
            if (audit.MetadataJson != null)
            {
                try
                {
                    using var doc = System.Text.Json.JsonDocument.Parse(audit.MetadataJson);
                    if (nic == null && doc.RootElement.TryGetProperty("Nic", out var nicElem)) nic = nicElem.GetString();
                    if (address == null && doc.RootElement.TryGetProperty("Address", out var addrElem)) address = addrElem.GetString();
                    if (familyCode == null && doc.RootElement.TryGetProperty("FamilyCode", out var codeElem)) familyCode = codeElem.GetString();
                }
                catch { }
            }
        }

        if (request.Status == VerificationStatus.Verified && string.IsNullOrEmpty(familyCode))
        {
            familyCode = $"FV-{Math.Abs(userId.GetHashCode()) % 9000 + 1000}";
        }

        var metadata = System.Text.Json.JsonSerializer.Serialize(new
        {
            Status = request.Status.ToString(),
            Reason = request.Reason?.Trim(),
            FamilyCode = familyCode,
            Nic = nic,
            Address = address
        });

        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            EventType = "FAMILY_HEAD_VERIFICATION_CHANGED",
            ResourceType = "FamilyHead",
            ResourceId = user.Id,
            Outcome = request.Status.ToString(),
            MetadataJson = metadata
        });

        await dbContext.SaveChangesAsync(cancellationToken);

        var member = family?.Members.FirstOrDefault(m => m.UserId == user.Id && m.Role == FamilyRole.Head);
        return new FamilyHeadDto(
            member?.Id ?? user.Id,
            user.Id,
            family?.Id ?? Guid.Empty,
            family?.Name ?? "Pending Setup",
            user.DisplayName,
            user.Email,
            family?.Members.Count ?? 0,
            request.Status,
            user.IsActive,
            user.CreatedAt,
            nic,
            address,
            familyCode);
    }

    public async Task<PagedResult<TriageCaseDto>> GetMyCasesAsync(int page, int pageSize, CancellationToken cancellationToken)
    {
        var doctor = await RequireVerifiedDoctorAsync(cancellationToken);
        (page, pageSize) = NormalizePage(page, pageSize);
        var now = DateTimeOffset.UtcNow;
        var query = dbContext.CaseAccessGrants.AsNoTracking()
            .Where(x => x.DoctorId == doctor.Id && x.RevokedAt == null && x.ExpiresAt > now)
            .Select(x => x.TriageCase!)
            .OrderByDescending(x => x.Priority).ThenBy(x => x.CreatedAt);
        var total = await query.CountAsync(cancellationToken);
        var items = await query.Skip((page - 1) * pageSize).Take(pageSize)
            // Names are released only for cases this doctor holds an active grant on.
            .Select(x => new TriageCaseDto(x.Id, x.EpisodeId, x.MemberId, x.Status, x.Priority, x.CreatedAt,
                x.CaseNumber, x.Member!.DisplayName, x.Member!.Family!.Name,
                dbContext.Approvals.Any(a => a.TriageCaseId == x.Id && a.Action == ApprovalAction.CloseReferral), x.SubmittedAt, null, null, false, false, null, null, null, x.FailureCode))
            .ToListAsync(cancellationToken);
        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            EventType = "DOCTOR_GRANTED_CASES_READ",
            ResourceType = "TriageCase",
            Outcome = "SUCCESS",
            MetadataJson = "{}"
        });
        await dbContext.SaveChangesAsync(cancellationToken);
        return new PagedResult<TriageCaseDto>(items, page, pageSize, total);
    }

    public async Task<PagedResult<ProcessingCaseDto>> GetProcessingCasesAsync(int page, int pageSize, CancellationToken cancellationToken)
    {
        var doctor = await RequireVerifiedDoctorAsync(cancellationToken);
        (page, pageSize) = NormalizePage(page, pageSize);
        var statuses = new[] { TriageStatus.Submitted, TriageStatus.Planning, TriageStatus.ContextReady, TriageStatus.Analysed, TriageStatus.RiskAssessed, TriageStatus.Validated, TriageStatus.FailedSafe };
        // Assignment is metadata routing only, never a clinical access grant.
        var query = dbContext.TriageCases.AsNoTracking().Where(x => statuses.Contains(x.Status) &&
            dbContext.FamilyDoctorAssignments.Any(a => a.FamilyId == x.Member!.FamilyId && a.DoctorId == doctor.Id && a.IsPrimary && a.EndedAt == null));
        var total = await query.CountAsync(cancellationToken);
        var items = await query.OrderBy(x => x.SubmittedAt).Skip((page - 1) * pageSize).Take(pageSize)
            .Select(x => new ProcessingCaseDto(x.Id, x.CaseNumber, x.Status, x.SubmittedAt ?? x.CreatedAt)).ToListAsync(cancellationToken);
        await WriteAuditAsync("DOCTOR_PROCESSING_INBOX_READ", "ProcessingInbox", doctor.Id, "SUCCESS", cancellationToken);
        await dbContext.SaveChangesAsync(cancellationToken);
        return new(items, page, pageSize, total);
    }

    public async Task<PagedResult<AvailableCaseDto>> GetAvailableCasesAsync(int page, int pageSize, CancellationToken cancellationToken)
    {
        await RequireVerifiedDoctorAsync(cancellationToken);
        (page, pageSize) = NormalizePage(page, pageSize);
        var now = DateTimeOffset.UtcNow;
        var slaCutoff = now.AddHours(-configuration.GetValue("Sla:DoctorResponseHours", 6));
        var query = dbContext.TriageCases.AsNoTracking().Where(x =>
            (x.Status == TriageStatus.PendingDoctorReview || x.Status == TriageStatus.LowConfidence || x.Status == TriageStatus.Claimed || x.Status == TriageStatus.Escalated) &&
            (!x.AccessGrants.Any(g => g.RevokedAt == null && g.ExpiresAt > now) ||
             x.AccessGrants.Any(g => g.RevokedAt == null && g.ExpiresAt > now && g.CreatedAt <= slaCutoff)) &&
            // A closed referral needs no further acknowledgement.
            !dbContext.Approvals.Any(a => a.TriageCaseId == x.Id && a.Action == ApprovalAction.CloseReferral));
        var total = await query.CountAsync(cancellationToken);
        // Pool reads never release submitted clinical text before a grant and review-start marker.
        var items = await query.OrderByDescending(x => x.Priority).ThenBy(x => x.CreatedAt).Skip((page - 1) * pageSize).Take(pageSize)
            .Select(x => new AvailableCaseDto(x.Id, x.Priority, x.CreatedAt, x.Status, x.CaseNumber, null)).ToListAsync(cancellationToken);
        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            EventType = "CASE_POOL_READ",
            ResourceType = "CasePool",
            Outcome = "SUCCESS",
            MetadataJson = "{}"
        });
        await dbContext.SaveChangesAsync(cancellationToken);
        return new PagedResult<AvailableCaseDto>(items, page, pageSize, total);
    }

    public Task<ApprovalDto> ClaimCaseAsync(Guid caseId, CancellationToken cancellationToken) =>
        dbContext.Database.CreateExecutionStrategy().ExecuteAsync(() => ClaimCaseAsyncCore(caseId, cancellationToken));

    private async Task<ApprovalDto> ClaimCaseAsyncCore(Guid caseId, CancellationToken cancellationToken)
    {
        await using var gate = await CaseLifecycleLock.AcquireAsync(dbContext, caseId, cancellationToken);
        var doctor = await RequireVerifiedDoctorAsync(cancellationToken);
        var triageCase = await dbContext.TriageCases.SingleOrDefaultAsync(
            x => x.Id == caseId && (x.Status == TriageStatus.PendingDoctorReview || x.Status == TriageStatus.LowConfidence || x.Status == TriageStatus.Claimed || x.Status == TriageStatus.Escalated),
            cancellationToken) ?? throw new NotFoundException();
        if (await EmergencyCaseAccess.IsClosedAsync(dbContext, caseId, cancellationToken)) throw new NotFoundException();
        var now = DateTimeOffset.UtcNow;
        var slaCutoff = now.AddHours(-configuration.GetValue("Sla:DoctorResponseHours", 6));
        var existingUnrevokedGrants = await dbContext.CaseAccessGrants
            .Where(x => x.TriageCaseId == caseId && x.RevokedAt == null)
            .ToListAsync(cancellationToken);
        if (existingUnrevokedGrants.Any(x => x.ExpiresAt > now && x.CreatedAt > slaCutoff))
        {
            throw new ConflictException("Case is already claimed.");
        }
        foreach (var grant in existingUnrevokedGrants) grant.RevokedAt = now;

        dbContext.CaseAccessGrants.Add(new CaseAccessGrant
        {
            TriageCaseId = caseId,
            DoctorId = doctor.Id,
            ExpiresAt = now.AddHours(configuration.GetValue("Grants:ExpiryHours", 48)),
            Reason = "CASE_CLAIM"
        });
        if (triageCase.Status != TriageStatus.Escalated) triageCase.Status = TriageStatus.Claimed;
        var approval = new Approval
        {
            TriageCaseId = caseId,
            DoctorId = doctor.Id,
            Action = ApprovalAction.RequestInformation,
            DoctorNotes = triageCase.Status == TriageStatus.Escalated ? EmergencyAcknowledgedNote : "Case claimed for review.",
            DecidedAt = now
        };
        dbContext.Approvals.Add(approval);
        // A referral can be re-acknowledged once a grant passes the SLA; the patient is told only the first time.
        if (triageCase.Status == TriageStatus.Escalated &&
            !await dbContext.Approvals.AnyAsync(x => x.TriageCaseId == caseId && x.DoctorNotes == EmergencyAcknowledgedNote, cancellationToken))
        {
            await NotifyEmergencyAcknowledgedAsync(triageCase.MemberId, cancellationToken);
        }
        await CaseLifecycle.MarkReviewAsync(dbContext, caseId, triageCase.MemberId, currentUser.UserId, cancellationToken);
        await WriteAuditAsync("CASE_CLAIMED", "TriageCase", caseId, "SUCCESS", cancellationToken, triageCase.MemberId);
        try
        {
            await dbContext.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            dbContext.ChangeTracker.Clear();
            throw new ConflictException("Case was claimed by another doctor.");
        }
        await gate.CompleteAsync(cancellationToken);
        return MapApproval(approval);
    }

    public Task<ApprovalDto> DecideCaseAsync(Guid caseId, ApprovalRequest request, CancellationToken cancellationToken) =>
        dbContext.Database.CreateExecutionStrategy().ExecuteAsync(() => DecideCaseAsyncCore(caseId, request, cancellationToken));

    private async Task<ApprovalDto> DecideCaseAsyncCore(Guid caseId, ApprovalRequest request, CancellationToken cancellationToken)
    {
        await using var gate = await CaseLifecycleLock.AcquireAsync(dbContext, caseId, cancellationToken);
        var doctor = await RequireVerifiedDoctorAsync(cancellationToken);
        var triageCase = await dbContext.TriageCases.SingleOrDefaultAsync(x => x.Id == caseId, cancellationToken) ?? throw new NotFoundException();
        if (triageCase.Status is not (TriageStatus.PendingDoctorReview or TriageStatus.LowConfidence or TriageStatus.Claimed))
        {
            throw new ConflictException("Case already has a terminal decision.");
        }
        var grant = await dbContext.CaseAccessGrants.AsNoTracking()
            .Where(x => x.TriageCaseId == caseId && x.DoctorId == doctor.Id)
            .OrderByDescending(x => x.ExpiresAt)
            .FirstOrDefaultAsync(cancellationToken);
        if (grant is null || !CaseGrantPolicy.HasAccess(grant.ExpiresAt, grant.RevokedAt, DateTimeOffset.UtcNow))
        {
            throw new NotFoundException();
        }

        var approving = request.Action is ApprovalAction.Approve or ApprovalAction.ReviseAndApprove;
        if (approving && string.IsNullOrWhiteSpace(request.FinalAdvisory))
        {
            throw new ValidationException(new Dictionary<string, string[]> { ["finalAdvisory"] = ["Doctor-approved guidance is required."] });
        }

        if (approving)
        {
            if (!SafetyValidationService.IsApprovedPatientGuidance(request.FinalAdvisory!))
            {
                throw new ValidationException(new Dictionary<string, string[]> { ["finalAdvisory"] = ["Select an approved non-diagnostic guidance statement."] });
            }
        }

        triageCase.Status = request.Action switch
        {
            ApprovalAction.Approve => TriageStatus.Approved,
            ApprovalAction.ReviseAndApprove => TriageStatus.ApprovedRevised,
            ApprovalAction.Reject => TriageStatus.Rejected,
            ApprovalAction.Escalate => TriageStatus.Escalated,
            _ => TriageStatus.PendingDoctorReview
        };
        var approval = new Approval
        {
            TriageCaseId = caseId,
            DoctorId = doctor.Id,
            Action = request.Action,
            DoctorNotes = request.DoctorNotes?.Trim(),
            FinalAdvisory = approving ? request.FinalAdvisory!.Trim() : null,
            DecidedAt = DateTimeOffset.UtcNow
        };
        dbContext.Approvals.Add(approval);
        if (triageCase.Status is TriageStatus.Approved or TriageStatus.ApprovedRevised or TriageStatus.Rejected or TriageStatus.Escalated)
        {
            var activeGrants = await dbContext.CaseAccessGrants
                .Where(x => x.TriageCaseId == caseId && x.RevokedAt == null)
                .ToListAsync(cancellationToken);
            foreach (var activeGrant in activeGrants) activeGrant.RevokedAt = approval.DecidedAt;
            // The doctor has now decided, so an earlier overdue-review marker no longer describes this case.
            if (triageCase.FailureCode == "DOCTOR_RESPONSE_DELAY") triageCase.FailureCode = null;
        }
        await CaseLifecycle.MarkReviewAsync(dbContext, caseId, triageCase.MemberId, currentUser.UserId, cancellationToken);
        await WriteAuditAsync("CASE_DECISION", "TriageCase", caseId, "SUCCESS", cancellationToken, triageCase.MemberId);
        try
        {
            await dbContext.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            dbContext.ChangeTracker.Clear();
            throw new ConflictException("Case was decided by another doctor.");
        }
        await gate.CompleteAsync(cancellationToken);
        await gate.DisposeAsync();
        await notificationService.SendCaseStatusAsync(caseId, triageCase.Status, cancellationToken);
        return MapApproval(approval);
    }

    public async Task<PagedResult<AuditDto>> GetAuditAsync(Guid? subjectMemberId, int page, int pageSize, CancellationToken cancellationToken)
    {
        (page, pageSize) = NormalizePage(page, pageSize);
        var query = dbContext.AuditLogs.AsNoTracking();
        if (currentUser.UserType == UserType.Admin)
        {
            if (subjectMemberId is not null)
            {
                query = query.Where(x => x.SubjectMemberId == subjectMemberId);
            }
        }
        else if (currentUser.UserType == UserType.FamilyUser)
        {
            var adultCutoff = DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-18);
            var allowedMembers = dbContext.Members.Where(x => x.UserId == currentUser.UserId ||
                (x.Family!.Members.Any(m => m.UserId == currentUser.UserId && m.Role == FamilyRole.Head) && x.DateOfBirth > adultCutoff))
                .Select(x => x.Id);
            query = query.Where(x => x.SubjectMemberId != null && allowedMembers.Contains(x.SubjectMemberId.Value));
            if (subjectMemberId is not null)
            {
                query = query.Where(x => x.SubjectMemberId == subjectMemberId);
            }
        }
        else
        {
            throw new ForbiddenException();
        }

        var total = await query.CountAsync(cancellationToken);
        var items = await query.OrderByDescending(x => x.CreatedAt).Skip((page - 1) * pageSize).Take(pageSize)
            .Select(x => new AuditDto(x.Id, x.EventType, x.ResourceType, x.ResourceId, x.Outcome, x.CreatedAt))
            .ToListAsync(cancellationToken);
        return new PagedResult<AuditDto>(items, page, pageSize, total);
    }

    private async Task<Doctor> RequireVerifiedDoctorAsync(CancellationToken cancellationToken) =>
        currentUser.UserType == UserType.Doctor
            ? await dbContext.Doctors.SingleOrDefaultAsync(x => x.UserId == currentUser.UserId && x.VerificationStatus == VerificationStatus.Verified, cancellationToken)
                ?? throw new ForbiddenException()
            : throw new ForbiddenException();

    private void RequireAdmin()
    {
        if (currentUser.UserType != UserType.Admin)
        {
            throw new ForbiddenException();
        }
    }

    private const string EmergencyAcknowledgedNote = "Emergency referral acknowledged.";

    /// <summary>
    /// Tells the patient a doctor has seen their referral. For a minor the family head is told too,
    /// matching who receives case status changes. The text repeats the referral; it is not AI output.
    /// </summary>
    private async Task NotifyEmergencyAcknowledgedAsync(Guid memberId, CancellationToken cancellationToken)
    {
        var recipients = await EmergencyCaseAccess.PatientRecipientsAsync(dbContext, memberId, cancellationToken);
        foreach (var userId in recipients)
        {
            dbContext.PortalNotifications.Add(new PortalNotification
            {
                UserId = userId,
                Type = "EMERGENCY_ACKNOWLEDGED",
                Title = "A doctor has seen your referral",
                Body = "A doctor has seen your urgent care referral. Please continue to seek in-person care now.",
                LinkPath = "/triage"
            });
        }
    }

    private static IReadOnlyList<string> ParseSymptoms(string symptomsJson)
    {
        try
        {
            return JsonSerializer.Deserialize<IReadOnlyList<string>>(symptomsJson) ?? [];
        }
        catch (JsonException)
        {
            return [];
        }
    }

    /// <summary>A ten-year band, so the pool never carries a date of birth or an exact age.</summary>
    private static string AgeBand(DateOnly dateOfBirth, DateOnly today)
    {
        var age = today.Year - dateOfBirth.Year;
        if (dateOfBirth > today.AddYears(-age)) age--;
        if (age < 18) return "Under 18";
        if (age >= 80) return "80+";
        var low = Math.Max(18, age / 10 * 10);
        return $"{low}–{age / 10 * 10 + 9}";
    }

    private async Task WriteAuditAsync(string eventType, string resourceType, Guid resourceId, string outcome, CancellationToken cancellationToken, Guid? subjectMemberId = null, string? metadataJson = null)
    {
        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            SubjectMemberId = subjectMemberId,
            EventType = eventType,
            ResourceType = resourceType,
            ResourceId = resourceId,
            Outcome = outcome,
            MetadataJson = metadataJson
        });
        await Task.CompletedTask;
    }

    private static string NormalizeRegistration(string value)
    {
        var normalized = new string(value.Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());
        if (normalized.Length < 4 || normalized.Length > 30)
        {
            throw new ValidationException(new Dictionary<string, string[]> { ["registrationNumber"] = ["Registration number format is invalid."] });
        }
        return normalized;
    }

    private static DoctorDto MapDoctor(Doctor x, string? registrationNumber = null) =>
        new(x.Id, x.UserId, x.RegistrationNumberLastFour, x.VerificationStatus, x.Specialty, x.HospitalClinic, x.PhoneNumber, x.User?.DisplayName, x.User?.Email, registrationNumber);
    private static ApprovalDto MapApproval(Approval x) => new(x.Id, x.TriageCaseId, x.DoctorId, x.Action, x.DecidedAt);
    private static (int Page, int PageSize) NormalizePage(int page, int pageSize) => (Math.Max(page, 1), Math.Clamp(pageSize, 1, 100));

    private static string? MaskNationalId(string? lastFour) => string.IsNullOrEmpty(lastFour) ? null : $"••••{lastFour}";

    private static string? FormatAddress(Domain.Identity.UserProfile profile)
    {
        var parts = new[] { profile.AddressLine1, profile.AddressLine2, profile.City, profile.District, profile.PostalCode }
            .Where(x => !string.IsNullOrWhiteSpace(x));
        var text = string.Join(", ", parts);
        return text.Length == 0 ? null : text;
    }
}
